package it.cavallium.rockserver.core.impl.test;

import it.cavallium.rockserver.core.common.ColumnSchema;
import it.cavallium.rockserver.core.common.distributed.*;
import it.cavallium.rockserver.core.config.ConfigParser;
import it.cavallium.rockserver.core.impl.MergeOperatorRegistry;
import it.cavallium.rockserver.core.impl.rocksdb.*;
import it.unimi.dsi.fastutil.ints.IntArrayList;
import it.unimi.dsi.fastutil.objects.ObjectArrayList;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.slf4j.LoggerFactory;
import static org.junit.jupiter.api.Assertions.*;

class NativeMultiDomainBootstrapTest {
    @TempDir(factory=DiskTestDirectory.class) Path root;
    final NativeOperatorInstallationTest helper=new NativeOperatorInstallationTest();
    final UUID domainB=new UUID(0,7002),columnB=new UUID(0,7004),metadata=new UUID(0,7003);
    ColumnSchema plain(){return ColumnSchema.of(IntArrayList.of(1),new ObjectArrayList<>(),true);}
    DistributedSchema secondary(DistributedSchema first,UUID domain,UUID column,long api,String name){return new DistributedSchema(first.clusterId(),first.databaseId(),domain,1,0,List.of(new DistributedSchema.Column(api,column,name,plain(),null)));}
    DistributedStoragePool open(Path path,Collection<DistributedSchema> schemas,Map<UUID,String> names,Map<UUID,String> plain){return DistributedStoragePool.open(path,ConfigParser.parseDefault(),LoggerFactory.getLogger(getClass()),schemas,names,plain);}
    ReplicatedRangeStore range(DistributedStoragePool pool,UUID group,DistributedSchema schema,Map<UUID,String> names)throws Exception {var selected=new HashMap<UUID,String>();schema.columnIds().forEach(id->selected.put(id,names.get(id)));var merges=schema.columns().stream().filter(c->c.operator()!=null).map(DistributedSchema.Column::columnId).collect(java.util.stream.Collectors.toSet());var store=pool.openRange(new RangeOwnership.Owner(group,1),new RangeOwnership.Interval(schema.domainId(),schema.columnIds(),null,null),schema.digest(),selected,merges);store.enableLogicalSchema(schema);return store;}
    void requireMetadataBirth(DistributedStoragePool pool,String boundary)throws Exception {
        var loaded=helper.loaded(pool);var state=loaded.db().getStartupColumns().entrySet().stream().filter(entry->new String(entry.getKey().getName(),java.nio.charset.StandardCharsets.US_ASCII).equals(DistributedStoragePool.STATE_COLUMN)).findFirst().orElseThrow().getValue();var decoder=DistributedStoragePool.class.getDeclaredMethod("decodeBirths",byte[].class);decoder.setAccessible(true);var births=(Map<?,?>)decoder.invoke(null,(Object)loaded.db().get().get(state,"CF-BIRTH".getBytes(java.nio.charset.StandardCharsets.US_ASCII)));assertTrue(births.containsKey(metadata),boundary);
    }
    DistributedCommand put(ReplicatedRangeStore store,UUID column,int value,long sequence){return new DistributedCommand(store.ownership().owner().groupId(),1,store.schemaDigest(),new OperationId(new UUID(0,7010),1,sequence),List.of(new Mutation(Mutation.Kind.PUT,column,new byte[]{1},new byte[]{(byte)value})));}
    @Test void twoDomainsOperatorAndMetadataShareQualifiedPoolAndEvolvedBindingsReopenCanonicalOriginal()throws Exception {
        Path path=root.resolve("aggregate");byte[] jar=DistributedMergeOperatorRegistryTest.classes(NativeOperatorInstallationTest.AppendOperator.class);var first=helper.target(jar);var second=secondary(first,domainB,columnB,2,"secondary");var names=Map.of(first.columns().getFirst().columnId(),"primary",columnB,"secondary-data");var plain=Map.of(metadata,"home-meta");var operator=first.columns().getFirst().operator();DistributedStoragePool.stageOperator(path,operator,new MergeOperatorRegistry.DeterministicContract("append-contract",1,true),jar);UUID groupA=new UUID(0,7100),groupB=new UUID(0,7101),later=new UUID(0,7102);DistributedSchema evolved;
        try(var pool=open(path,List.of(first,second),names,plain)){pool.configureSnapshotAdmission(PoolSnapshotAdmission.Limits.defaults());var pressure=pool.currentSnapshotPressure();assertTrue(pressure.estimatedBytes()>=0);assertTrue(pressure.freeBytes()>=0);assertEquals(0,pressure.pinReservations());assertEquals(0,pool.snapshotAdmissionStats().pins());assertEquals(0,helper.loaded(pool).db().get().getLongProperty("rocksdb.num-snapshots"));var a=range(pool,groupA,first,names);var b=range(pool,groupB,second,names);a.apply(new ApplyPosition(1,0),put(a,first.columns().getFirst().columnId(),2,0));a.apply(new ApplyPosition(1,1),new DistributedCommand(groupA,1,first.digest(),new OperationId(new UUID(0,7010),1,1),List.of(new Mutation(Mutation.Kind.MERGE,first.columns().getFirst().columnId(),new byte[]{1},new byte[]{3}))));b.apply(new ApplyPosition(1,0),put(b,columnB,9,0));assertArrayEquals(new byte[]{2,3},a.readCurrentPoint(first.columns().getFirst().columnId(),new byte[]{1}));assertArrayEquals(new byte[]{9},b.readCurrentPoint(columnB,new byte[]{1}));var meta=pool.openRange(new RangeOwnership.Owner(new UUID(0,7103),1),new RangeOwnership.Interval(new UUID(0,7104),Set.of(metadata),null,null),new byte[32],plain,Set.of());meta.apply(new ApplyPosition(1,0),new DistributedCommand(meta.ownership().owner().groupId(),1,new byte[32],new OperationId(new UUID(0,7011),1,0),List.of(new Mutation(Mutation.Kind.PUT,metadata,new byte[]{1},new byte[]{8}))));requireMetadataBirth(pool,"Metadata birth missing immediately after metadata write");
            var columns=new ArrayList<>(second.columns());columns.add(new DistributedSchema.Column(3,later,"later",plain(),null));evolved=new DistributedSchema(second.clusterId(),second.databaseId(),domainB,2,0,columns);var peer=new ReplicaDescriptor(new UUID(0,7105),new UUID(0,7106),new UUID(0,7107),"peer","localhost:17100",ReplicaDescriptor.Role.VOTER);var descriptor=new RangeDescriptor(groupB,groupB,1,1,null,null,RangeDescriptor.TopologyState.ACTIVE,List.of(peer));var directory=new RangeDirectory(second.clusterId(),second.databaseId(),domainB,1,second.digest(),1,second.columnIds(),0,List.of(descriptor));var change=new SchemaChange.Definition(new UUID(0,7108),new OperationId(new UUID(0,7109),1,0),directory,second,evolved);b.applySchemaFence(new ApplyPosition(1,1),change.header());var installed=pool.installSchema(b,new ApplyPosition(1,2),change,Map.of(columnB,"secondary-data",later,"later-data"),Set.of());b.applySchemaActivation(new ApplyPosition(1,3),installed.proof(),new UUID(0,7110),new ApplyPosition(1,10));assertArrayEquals(first.digest(),a.schemaDigest());requireMetadataBirth(pool,"Metadata birth disappeared during unrelated domain schema evolution");
        }
        try(var pool=open(path,List.of(second,first),names,plain)){var a=range(pool,groupA,first,names);var b=range(pool,groupB,evolved,Map.of(columnB,"secondary-data",later,"later-data"));assertArrayEquals(new byte[]{2,3},a.readCurrentPoint(first.columns().getFirst().columnId(),new byte[]{1}));assertArrayEquals(new byte[]{9},b.readCurrentPoint(columnB,new byte[]{1}));assertEquals(2,b.installedSchema().schemaEpoch());assertNull(b.readCurrentPoint(later,new byte[]{1}));}
        assertThrows(IllegalStateException.class,()->open(path,List.of(first),Map.of(first.columns().getFirst().columnId(),"primary"),plain));assertThrows(IllegalStateException.class,()->open(path,List.of(first,evolved),Map.of(first.columns().getFirst().columnId(),"primary",columnB,"secondary-data",later,"later-data"),plain));
        Path index=path.resolveSibling(path.getFileName()+".operators").resolve("bindings");byte[] bytes=Files.readAllBytes(index);assertEquals(1,bytes[4]);bytes[5]^=1;Files.write(index,bytes);assertThrows(IllegalStateException.class,()->open(path,List.of(first,second),names,plain));
    }
    @Test void collisionsMissingAggregateBindingAndForeignDatabaseRejectBeforeNativeExposure()throws Exception {
        var first=new DistributedSchema(new UUID(0,7200),new UUID(0,7201),new UUID(0,7202),1,0,List.of(new DistributedSchema.Column(1,new UUID(0,7203),"first",plain(),null)));var second=secondary(first,domainB,columnB,2,"second");var names=Map.of(first.columns().getFirst().columnId(),"one",columnB,"two");
        var invalid=List.of(List.of(first,secondary(first,first.domainId(),columnB,2,"second")),List.of(first,secondary(first,domainB,first.columns().getFirst().columnId(),2,"second")),List.of(first,secondary(first,domainB,columnB,1,"second")),List.of(first,secondary(first,domainB,columnB,2,"first")),List.of(first,new DistributedSchema(first.clusterId(),UUID.randomUUID(),domainB,1,0,second.columns())));
        int n=0;for(var schemas:invalid){Path path=root.resolve("invalid-"+n++);assertThrows(IllegalArgumentException.class,()->open(path,schemas,names,Map.of()));assertFalse(Files.exists(path.resolve("CURRENT")));}
        Path missing=root.resolve("missing");assertThrows(IllegalArgumentException.class,()->open(missing,List.of(first,second),Map.of(first.columns().getFirst().columnId(),"one"),Map.of()));assertFalse(Files.exists(missing.resolve("CURRENT")));Path shared=root.resolve("name-collision");assertThrows(IllegalArgumentException.class,()->open(shared,List.of(first,second),Map.of(first.columns().getFirst().columnId(),"same",columnB,"same"),Map.of()));assertFalse(Files.exists(shared.resolve("CURRENT")));Path meta=root.resolve("meta-collision");assertThrows(IllegalArgumentException.class,()->open(meta,List.of(first,second),names,Map.of(metadata,"one")));assertFalse(Files.exists(meta.resolve("CURRENT")));
    }
}
